mapper.select:
select br.patient_id as patientId, ifnull(sum(br.receivable_amount), 0) as billTotalOriginalPrice, ifnull(sum(br.privilege_amount), 0) as billTotalPrivilegePrice, ifnull(sum(br.actual_receivable_amount), 0) as billTotalActualPrice, ifnull(sum(br.received_amount), 0) as billTotalReceivedPrice, ifnull(sum(br.debt_amount), 0) as billTotalArrears from bill_record br where inservice = true and br.patient_id in
#{patientId}
group by br.patient_id

select br.* from bill_record br where inservice = true and
br.treatment_record_id in

    #{treatmentId}

select br.treatment_record_id as id, br.patient_id as patientId, r.first_visit as firstVisit, r.dentist_id as dentistId, tr.treat_start_time as treatStartTime from bill_record br left join treatment_record tr on tr.patient_id = br.patient_id and tr.id = br.treatment_record_id left join registered r on r.patient_id = br.patient_id and r.id = tr.registered_id where date_format(br.crt_time, '%Y-%m-%d') = date_format(#{currentDate}, '%Y-%m-%d')
and br.org_id = #{orgId}
group by br.treatment_record_id, br.patient_id, r.first_visit, r.dentist_id, treat_start_time order by tr.treat_start_time desc

SELECT
SUM( IFNULL( br.actual_receivable_amount, 0 ) ) AS actualReceivedAmountCompleted
FROM
bill_record br

    AND br.inservice = 1

        AND DATE_FORMAT(br.crt_time, '%Y-%m') = #{query.businessDate}


        AND DATE_FORMAT(br.crt_time, '%Y') = #{query.businessDate}


        AND br.org_id IN

            #{item}

SELECT IFNULL(SUM( odpr.actual_receivable ) + SUM( odpr.coupon_workload ), 0) AS workloadAmountCompleted FROM order_detail_pay_record odpr
AND odpr.inservice = 1
AND DATE_FORMAT(odpr.crt_time, '%Y-%m') = #{query.businessDate}
AND DATE_FORMAT(odpr.crt_time, '%Y') = #{query.businessDate}
AND odpr.order_detail_id IN ( SELECT od.id FROM order_detail od
AND od.inservice = 1 AND od.executor_id IS NOT NULL
AND od.org_id IN
#{item}
)

SELECT
SUM( br.actual_receivable_amount ) AS actualReceivedAmountCompleted
FROM
bill_record br

    AND br.inservice = 1

        AND br.org_id = #{query.orgId}


        AND DATE_FORMAT(br.crt_time, '%Y-%m') >= #{query.startDate}


        AND DATE_FORMAT(br.crt_time, '%Y-%m') <= #{query.endDate}
